    elif i == "3":
        secret_exponent = bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code
    elif i == "4":
        secret_exponent = bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent
    elif i == "5":
        secret_exponent = bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code
    elif i == "6":
        secret_exponent = bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent
    elif i == "7":
        secret_exponent = bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code + bip32_pub_node.secret_exponent + bip32_pub_node.chain_code
    elif i == "8":
