                result['counters'] = record['fields']['counters']
            else:
                for task in record['fields']['tasks']:
                    if task['status'] == 'SUCCEEDED' and 'COUNTERS' in task:
                        task_to_counters[task['taskid']] = task['COUNTERS']
        elif record['type'] == 'TASK':
