    if not isinstance(index_info, dict):
        raise TypeError("index_info must be a dictionary")
    if "ReadCapacityUnits" not in index_info or "WriteCapacityUnits" not in index_info:
        raise ValueError("index_info must contain 'ReadCapacityUnits' and 'WriteCapacityUnits' keys")
    if not isinstance(index_info["ReadCapacityUnits"], int):
        raise TypeError("ReadCapacityUnits must be an integer")
    if not isinstance(index_info["WriteCapacityUnits"], int):
        raise TypeError("WriteCapacityUnits must be an integer")

# Update the global indexes in DynamoDB
