    {
        "Update": {
            "IndexName": index_name,
            "ProvisionedThroughput": {
                "ReadCapacityUnits": index_info["ReadCapacityUnits"],
                "WriteCapacityUnits": index_info["WriteCapacityUnits"]
            }
        }
    }
    for index_name, index_info in global_indexes.items()
])

# Check if the global indexes were successfully updated
if self.describe()["GlobalSecondaryIndexes"] == global_indexes:
