"""
sentences = []
paragraphs = []
paragraph = []
for line in self.text.splitlines():
    line = line.strip()
    if line:
        sentences.append(Sentence(line))
        paragraph.append(line)
    else:
        if paragraph:
            paragraphs.append(Paragraph(" ".join(paragraph)))
        paragraph = []
if paragraph:
    paragraphs.append(Paragraph(" ".join(paragraph)))
return Document("\n\n".join(paragraphs), sentences)

"""This function converts a given specification to a CpuResource value. The specification can be a float, int, or string. It handles different formats of the specification and returns the corresponding CpuResource value. Note to check ValueError.

:param cls: Class. The class itself.
:param spec: Any. The specification to be converted to CpuResource.
:return: float. The converted CpuResource value.
"""
if isinstance(spec, (int, float)):
    return cls(spec)
elif isinstance(spec, str):
    if spec.endswith("m"):
        return cls(int(spec[:-1]))
    elif spec.endswith("vcpu"):
        return cls(int(spec[:-4]))
    else:
        raise ValueError(
            f"Invalid CPU resource spec: {spec}. "
            "Supported formats: <int>, <int>m, <int>vcpu"
        )
else:
    raise ValueError(
        f"Invalid CPU resource spec: {spec}. "
        "Supported formats: <int>, <int>m, <int>vcpu"
    )

