    """This function expands the lists of all different available alternative recipe combinations. It adds the dependencies for the recipes that do not have alternatives. It split up lists by available alternatives. This function is used for basic bootstrap compatibility checks.

    :param recipes: List. The list of recipes to expand.
    :param ctx: Context. The context object.
    :return: List of lists. The expanded recipe combinations with added dependencies.
    """
    # Expand the list of recipes
    expanded_recipes = []
    for recipe in recipes:
        if recipe.alternatives:
            for alternative in recipe.alternatives:
                expanded_recipes.append(recipe.copy(alternative))
        else:
            expanded_recipes.append(recipe)

    # Add the dependencies for the recipes that do not have alternatives
    for recipe in expanded_recipes:
        if not recipe.alternatives:
            recipe.dependencies = recipe.dependencies or []
            recipe.dependencies.extend(recipe.dependencies_without_alternatives)

    # Split up lists by available alternatives
    expanded_recipes = [list(group) for group in groupby(expanded_recipes, lambda x: x.alternatives)]

    # Add the dependencies for the recipes that do not have alternatives
    for recipe_list in expanded_recipes:
        for recipe in recipe_list:
            if not recipe.alternatives:
                recipe.dependencies = recipe.dependencies or []
                recipe.dependencies.extend(recipe.dependencies_without_alternatives)

    return expanded_recipes

