        bounds = (np.min(array), np.max(array))
    if dtype is None:
        dtype = np.float32 if np.issubdtype(array.dtype, np.integer) else array.dtype
    if random_state is None:
        random_state = np.random.RandomState()
    if accountant is not None:
        accountant.log(len(array), 'variance')
