        axis += array.ndim
    if axis >= array.ndim:
        raise ValueError('axis out of range')
    if axis != array.ndim - 1:
        array = np.moveaxis(array, axis, -1)
    array = array.reshape(-1, array.shape[-1])
    array = array[~np.isnan(array).any(axis=1)]
    if array.size == 0:
