    """This function returns the immediate down revisions for a given revision, excluding any dependencies that are still dependencies of ancestors.

    :param self: Revision. An instance of the Revision class.
    :return: Tuple of strings. The immediate down revisions for the given revision.
    """
    down_revisions = self.down_revisions
    if not down_revisions:
        return ()
    if len(down_revisions) == 1:
        return down_revisions
    # if there are multiple down revisions, we need to check if any of them are still dependencies of ancestors
    # if so, we need to remove them from the list of down revisions
    ancestor_dependencies = set()
    for down_revision in down_revisions:
        ancestor_dependencies.update(self.ancestor_dependencies(down_revision))
    return tuple(down_revision for down_revision in down_revisions if down_revision not in ancestor_dependencies)


