    :param self: DataSet. An instance of the DataSet class.
    :param table: String. The name of the table to update the cache for. Defaults to None.
    :return: No return values.
    """
    if table is None:
        for table_name in self.tables:
            self.update_cache(table_name)
    else:
        if table not in self.tables:
            raise ValueError(f"Table '{table}' not found in DataSet")
        self.cache[table] = self.get_table_cache(table)
        self.models[table] = self.get_table_model(table)
        for related_table in self.get_related_tables(table):
            self.update_cache(related_table)

